def shortest_front_palindrome(s):
    joined = s + "#" + s[::-1]
    prefix = [0] * len(joined)
    for i in range(1, len(joined)):
        match = prefix[i - 1]
        while match and joined[i] != joined[match]:
            match = prefix[match - 1]
        if joined[i] == joined[match]:
            match += 1
        prefix[i] = match
    return s[prefix[-1]:][::-1] + s

